#include <string.h>
long long ph(long long v){long long r=v,p;for(p=2;p*p<=v;p++)if(v%p==0){while(v%p==0)v/=p;r-=r/p;}if(v>1)r-=r/v;return r;}int main(void){int n,i;static long long a[500005];if(scanf("%d",&n)!=1)return 1;for(i=0;i<n;i++)scanf("%lld",&a[i]);long long s=0;int c=0;for(i=0;i<n;i++){long long x=a[i];if((x >= 2) & (ph(x) % 2 == 0)){s+=x;c++;}}printf("%lld\n",c?s/c:-1);return 0;}
